import { useEffect, useMemo, useRef, useState } from 'react'
import {
  ArrowLeft, ArrowRight, BarChart3, BookOpen, CalendarDays,
  Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3,
  ClipboardCheck, FileText, GraduationCap, Home, Lightbulb, LogOut, Menu, MessageCircle,
  Send, Sparkles, Target, TrendingUp, Trash2,
  Users, WandSparkles, X
} from 'lucide-react'
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis
} from 'recharts'
import { colorClasses, examQuestions, subjects } from './data'
import { downloadBlob, getMaterialFile } from './localData'
import AuthPage from './AuthPage'
import TeacherPage from './TeacherPage'

const fmtDate = (date) => new Date(date).toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' })
const pct = (a, b) => Math.round((a / b) * 100)
const topicKey = (subjectId, topic) => `${subjectId}:${topic.id || topic.name}`
const routes = { home: 'Главная', subjects: 'Мои предметы', assistant: 'Учебный помощник', exam: 'Пробный экзамен', progress: 'Мой прогресс', teacher: 'Кабинет преподавателя' }

function useStoredState(key, initial) {
  const [value, setValue] = useState(() => {
    try { const saved = localStorage.getItem(key); return saved === null ? initial : JSON.parse(saved) } catch { return initial }
  })
  useEffect(() => {
    try { localStorage.setItem(key, JSON.stringify(value)) }
    catch { window.dispatchEvent(new CustomEvent('eduagent-storage-error')) }
  }, [key, value])
  return [value, setValue]
}
function getHashRoute() { return window.location.hash.replace(/^#\/?/, '') || 'home' }
function useRoute() {
  const [route, setRoute] = useState(getHashRoute)
  useEffect(() => { const onChange = () => setRoute(getHashRoute()); window.addEventListener('hashchange', onChange); return () => window.removeEventListener('hashchange', onChange) }, [])
  const go = (path) => { window.location.hash = `/${path}`; setRoute(path); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  return [route, go]
}
function IconBadge({ subject, size = 'md' }) {
  const color = colorClasses[subject.color] || colorClasses.violet
  return <div className={`${size === 'lg' ? 'h-16 w-16 rounded-2xl text-2xl' : 'h-12 w-12 rounded-2xl text-lg'} ${color.icon} grid shrink-0 place-items-center font-extrabold shadow-sm`}>{subject.icon || '✦'}</div>
}
function ProgressBar({ value, color = 'violet', height = 'h-2' }) {
  return <div className={`${height} w-full overflow-hidden rounded-full bg-slate-100`}><div className={`${height} ${colorClasses[color]?.bar || 'bg-violet-500'} rounded-full transition-all duration-700`} style={{ width: `${Math.max(0, Math.min(100, value || 0))}%` }} /></div>
}
function SectionTitle({ eyebrow, title, action, onAction }) {
  return <div className="mb-5 flex items-end justify-between gap-3"><div>{eyebrow && <div className="eyebrow mb-1">{eyebrow}</div>}<h2 className="text-xl font-extrabold tracking-tight text-slate-900 sm:text-2xl">{title}</h2></div>{action && <button className="text-link shrink-0" onClick={onAction}>{action}<ArrowRight size={16} /></button>}</div>
}
function Logo({ compact = false }) { return <div className="flex items-center gap-3"><div className="logo-mark"><Sparkles size={21} strokeWidth={2.5} /></div>{!compact && <div className="text-[21px] font-extrabold tracking-[-.06em] text-slate-900">edu<span className="text-violet-600">agent</span></div>}</div> }
function NavItem({ icon: Icon, label, active, onClick, badge }) { return <button className={`nav-item ${active ? 'nav-item-active' : ''}`} onClick={onClick}><Icon size={19} strokeWidth={active ? 2.4 : 2} /><span>{label}</span>{badge && <span className="ml-auto rounded-md bg-violet-100 px-1.5 py-0.5 text-[10px] font-extrabold text-violet-600">{badge}</span>}</button> }
function Sidebar({ route, go, account, logout, mobileOpen, setMobileOpen }) {
  const role = account.role
  const page = route.startsWith('subject/') ? 'subjects' : route
  const navigate = (path) => { go(path); setMobileOpen(false) }
  return <>
    {mobileOpen && <button aria-label="Закрыть меню" className="fixed inset-0 z-40 bg-slate-950/30 backdrop-blur-sm lg:hidden" onClick={() => setMobileOpen(false)} />}
    <aside className={`sidebar ${mobileOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <div className="mb-10 flex items-center justify-between px-2"><Logo /><button className="rounded-lg p-2 text-slate-500 lg:hidden" aria-label="Закрыть меню" onClick={() => setMobileOpen(false)}><X size={20} /></button></div>
      {role === 'student' && <div className="mb-3 px-4 text-[10px] font-extrabold uppercase tracking-[.18em] text-slate-400">Обучение</div>}
      {role === 'student' && <nav className="space-y-1" aria-label="Основная навигация">
        <NavItem icon={Home} label="Главная" active={page === 'home'} onClick={() => navigate('home')} />
        <NavItem icon={BookOpen} label="Мои предметы" active={page === 'subjects'} onClick={() => navigate('subjects')} />
        <NavItem icon={MessageCircle} label="Учебный помощник" active={page === 'assistant'} onClick={() => navigate('assistant')} badge="ОФЛАЙН" />
        <NavItem icon={ClipboardCheck} label="Пробный экзамен" active={page === 'exam'} onClick={() => navigate('exam')} />
        <NavItem icon={BarChart3} label="Мой прогресс" active={page === 'progress'} onClick={() => navigate('progress')} />
      </nav>}
      {role === 'teacher' && <><div className="mb-3 mt-9 px-4 text-[10px] font-extrabold uppercase tracking-[.18em] text-slate-400">Управление</div><nav className="space-y-1"><NavItem icon={Users} label="Преподавателю" active={page === 'teacher'} onClick={() => navigate('teacher')} /></nav></>}
      <div className="mt-auto pt-8">
        {role === 'student' && <div className="sidebar-promo"><div className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-white/20"><WandSparkles size={20} /></div><div className="text-sm font-extrabold">Учиться проще вместе</div><p className="mt-1 text-xs leading-5 text-white/70">Спроси помощника о сложной теме и получи понятное объяснение.</p><button className="mt-4 flex items-center gap-2 text-xs font-extrabold" onClick={() => navigate('assistant')}>Задать вопрос <ArrowRight size={14} /></button></div>}
        <button className="mt-5 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left hover:bg-slate-50" onClick={logout}><div className="grid h-10 w-10 place-items-center rounded-xl bg-blue-100 text-sm font-extrabold text-blue-700">{account.name?.[0]?.toUpperCase() || (role === 'teacher' ? 'П' : 'У')}</div><span className="min-w-0 flex-1"><span className="block truncate text-xs font-extrabold text-slate-800">{account.name}</span><span className="block text-[11px] text-slate-400">Выйти из аккаунта</span></span><LogOut size={16} className="text-slate-400" /></button>
      </div>
    </aside>
  </>
}
function Header({ route, account, go, logout, setMobileOpen }) {
  const title = route.startsWith('subject/') ? 'Мои предметы' : routes[route] || 'EduAgent'
  return <header className="topbar"><div className="flex min-w-0 items-center gap-3"><button aria-label="Открыть меню" className="rounded-xl p-2 text-slate-600 hover:bg-slate-100 lg:hidden" onClick={() => setMobileOpen(true)}><Menu size={22} /></button><div className="hidden text-sm text-slate-400 sm:block">Обучение <span className="mx-2">/</span></div><div className="truncate text-sm font-bold text-slate-800">{title}</div></div><div className="flex items-center gap-3"><span className="hidden rounded-full bg-violet-50 px-3 py-1.5 text-xs font-bold text-violet-600 sm:inline-flex"><span className="mr-1.5 h-1.5 w-1.5 self-center rounded-full bg-violet-500" /> {account.role === 'teacher' ? 'Преподаватель' : '9 класс'}</span>{account.role === 'student' && <button className="relative grid h-10 w-10 place-items-center rounded-xl border border-slate-100 bg-white text-slate-500 hover:text-violet-600" title="Открыть пробный тест" onClick={() => go('exam')}><ClipboardCheck size={18} /></button>}<button className="grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-violet-500 to-blue-600 text-sm font-extrabold text-white shadow-md shadow-violet-200" title="Выйти из аккаунта" onClick={logout}>{account.name?.[0]?.toUpperCase() || 'У'}</button></div></header>
}
function SubjectCard({ subject, go, compact = false }) {
  const color = colorClasses[subject.color] || colorClasses.violet
  return <button className={`subject-card group text-left ${compact ? 'p-5' : 'p-6'}`} onClick={() => go(`subject/${subject.id}`)}><div className="flex items-start justify-between"><IconBadge subject={subject} /><span className="grid h-8 w-8 place-items-center rounded-full bg-slate-50 text-slate-400 transition-all group-hover:bg-violet-100 group-hover:text-violet-600"><ArrowRight size={17} /></span></div><h3 className="mt-5 text-base font-extrabold text-slate-900">{subject.name}</h3><p className="mt-1 truncate text-xs text-slate-400">{subject.current || 'Учебные материалы'}</p><div className="mt-5 flex items-center justify-between text-xs"><span className="text-slate-400">Прогресс</span><strong className={color.text}>{subject.progress || 0}%</strong></div><div className="mt-2"><ProgressBar value={subject.progress || 0} color={subject.color} /></div></button>
}
function HomePage({ allSubjects, results, sessions, go, studentName }) {
  const latest = results[0]
  const upcoming = sessions.filter(item => new Date(item.date).getTime() >= Date.now() - 3600000).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 3)
  return <div className="page-enter"><div className="mb-7 flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow mb-1">Твой учебный кабинет</div><h1 className="page-title">Привет, {studentName}! <span className="inline-block animate-wave">👋</span></h1><p className="page-subtitle">Продолжим путь к твоим целям? Сегодня отличный день, чтобы узнать что-то новое.</p></div><div className="date-pill"><CalendarDays size={16} /> {new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })}</div></div>
    <div className="hero-card"><div className="relative z-10 max-w-[530px]"><div className="mb-4 inline-flex items-center gap-2 rounded-full bg-white/20 px-3 py-1.5 text-[11px] font-extrabold uppercase tracking-wider text-white"><Sparkles size={13} /> Твой следующий шаг</div><h2 className="text-2xl font-extrabold leading-tight tracking-tight text-white sm:text-3xl">Большие результаты начинаются с маленьких шагов</h2><p className="mt-3 max-w-md text-sm leading-6 text-white/80">Продолжи тему «Квадратные уравнения» и закрепи знания на практике.</p><button className="mt-6 flex items-center gap-2 rounded-xl bg-white px-5 py-3 text-sm font-extrabold text-violet-700 shadow-lg shadow-indigo-950/10 transition hover:-translate-y-0.5" onClick={() => go('subject/math')}>Продолжить обучение <ArrowRight size={16} /></button></div><div className="hero-art"><div className="hero-art-ring"/><div className="hero-art-book"><BookOpen size={72} strokeWidth={1.5}/></div><div className="hero-art-star hero-art-star-one">✦</div><div className="hero-art-star hero-art-star-two">✧</div></div></div>
    <div className="mt-6 grid gap-4 sm:grid-cols-3"><div className="stat-card"><div className="stat-icon bg-violet-50 text-violet-600"><BookOpen size={21} /></div><div><div className="stat-number">{allSubjects.length}</div><div className="stat-label">Предметов изучаю</div></div></div><div className="stat-card"><div className="stat-icon bg-blue-50 text-blue-600"><Target size={21} /></div><div><div className="stat-number">{latest ? `${pct(latest.score, latest.total)}%` : '—'}</div><div className="stat-label">Последний результат</div></div></div><div className="stat-card"><div className="stat-icon bg-amber-50 text-amber-600"><TrendingUp size={21} /></div><div><div className="stat-number">{results.length}</div><div className="stat-label">Моих пробных тестов</div></div></div></div>
    <div className="mt-10"><SectionTitle eyebrow="ТВОИ КУРСЫ" title="Мои предметы" action="Все предметы" onAction={() => go('subjects')} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{allSubjects.slice(0, 3).map(subject => <SubjectCard key={subject.id} subject={subject} go={go} />)}</div></div>
    <div className="mt-8 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><div className="panel p-6"><SectionTitle eyebrow="УЧЕБНЫЙ ПЛАН" title="Продолжить изучение" /><div className="space-y-1">{allSubjects.slice(0, 3).map((subject, i) => <button key={subject.id} className="lesson-row" onClick={() => go(`subject/${subject.id}`)}><div className={`grid h-10 w-10 place-items-center rounded-xl ${colorClasses[subject.color]?.icon || colorClasses.violet.icon}`}><BookOpen size={18} /></div><div className="min-w-0 flex-1 text-left"><div className="truncate text-sm font-extrabold text-slate-800">{subject.current}</div><div className="mt-0.5 text-xs text-slate-400">{subject.name} · тема для изучения</div></div><span className="hidden rounded-full bg-slate-50 px-2.5 py-1 text-[11px] font-bold text-slate-500 sm:block">Тема {i + 1}</span><ChevronRight size={17} className="text-slate-400" /></button>)}</div></div><div className="panel p-6"><SectionTitle eyebrow="ПРОВЕРЬ ЗНАНИЯ" title="Пробный тест" /><div className="rounded-2xl bg-violet-50 p-4"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-xl bg-white text-violet-600"><CalendarDays size={21} /></div><div><div className="text-sm font-extrabold text-slate-900">Пробный тест по математике</div><div className="mt-0.5 text-xs text-slate-500">15 заданий · около 20 минут</div></div></div><p className="mt-4 text-xs leading-5 text-slate-500">Проверь свои знания и получи разбор результата сразу после завершения.</p><button className="primary-button mt-5 w-full" onClick={() => go('exam')}>Начать тест <ArrowRight size={16} /></button></div></div></div>
    {upcoming.length > 0 && <div className="mt-8 panel p-6"><SectionTitle eyebrow="РАСПИСАНИЕ" title="Ближайшие занятия" /><div className="grid gap-3 md:grid-cols-3">{upcoming.map(item => <button key={item.id} className="flex items-center gap-3 rounded-xl border border-slate-100 p-4 text-left transition hover:border-violet-200 hover:bg-violet-50" onClick={() => go(`subject/${item.subjectId}`)}><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-blue-50 text-blue-600"><CalendarDays size={20} /></div><span className="min-w-0"><strong className="block truncate text-xs text-slate-800">{item.title}</strong><small className="mt-1 block text-[11px] text-slate-500">{allSubjects.find(x => x.id === item.subjectId)?.name} · {new Date(item.date).toLocaleString('ru-RU', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</small></span></button>)}</div></div>}
  </div>
}
function SubjectsPage({ allSubjects, go }) { return <div className="page-enter"><div className="mb-8"><div className="eyebrow mb-1">УЧЕБНЫЕ НАПРАВЛЕНИЯ</div><h1 className="page-title">Мои предметы</h1><p className="page-subtitle">Выбери предмет, изучай темы и закрепляй знания на практике.</p></div><div className="mb-6 flex flex-wrap gap-2"><span className="chip chip-active">Все предметы <span className="ml-1 rounded-full bg-white/25 px-1.5">{allSubjects.length}</span></span><span className="chip">9 класс</span><span className="chip">Основная программа</span></div><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{allSubjects.map(subject => <SubjectCard key={subject.id} subject={subject} go={go} />)}</div><div className="mt-8 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-violet-100 bg-gradient-to-r from-violet-50 to-blue-50 p-6"><div className="flex items-center gap-4"><div className="grid h-12 w-12 place-items-center rounded-xl bg-white text-violet-600"><MessageCircle size={22} /></div><div><div className="font-extrabold text-slate-900">Остался вопрос по теме?</div><div className="mt-1 text-xs text-slate-500">Помощник объяснит материал простыми словами.</div></div></div><button className="secondary-button" onClick={() => go('assistant')}>Спросить помощника <ArrowRight size={16} /></button></div></div> }
function SubjectPage({ subject, customMaterials, completedTopics, setCompletedTopics, go, openAssistant }) {
  const [selected, setSelected] = useState(null)
  const [answer, setAnswer] = useState(null)
  useEffect(() => { setAnswer(null); setSelected(null) }, [subject.id])
  const color = colorClasses[subject.color] || colorClasses.violet
  const topics = subject.topics || []
  const materials = customMaterials.filter(item => item.subjectId === subject.id)
  const practice = subject.practice
  const toggleComplete = topic => setCompletedTopics(prev => ({ ...prev, [topicKey(subject.id, topic)]: !prev[topicKey(subject.id, topic)] }))
  const openMaterial = async item => {
    if (item.fileStored) {
      try {
        const file = await getMaterialFile(item.id)
        if (!file) throw new Error('Файл отсутствует в этом браузере.')
        downloadBlob(file, item.fileName)
      } catch (error) { window.alert(error.message || 'Не удалось открыть файл.') }
    } else {
      setSelected({ name: item.title, type: 'Материал', detail: item.description || (item.fileName ? 'Файл был добавлен в предыдущей версии и недоступен для скачивания.' : 'Описание не добавлено.') })
    }
  }
  return <div className="page-enter"><button className="mb-6 flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-violet-600" onClick={() => go('subjects')}><ArrowLeft size={17} /> Все предметы</button><div className={`rounded-[26px] border border-white bg-gradient-to-r ${color.soft} p-7 sm:p-9`}><div className="flex flex-wrap items-start justify-between gap-5"><div className="flex items-start gap-5"><IconBadge subject={subject} size="lg" /><div><div className="eyebrow mb-1">ПРЕДМЕТ · 9 КЛАСС</div><h1 className="text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">{subject.name}</h1><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">{subject.description}</p><div className="mt-4 flex flex-wrap gap-4 text-xs font-bold text-slate-500"><span className="flex items-center gap-1.5"><BookOpen size={14} /> {subject.lessons || 0} / {subject.total || 0} уроков</span><span className="flex items-center gap-1.5"><Users size={14} /> {subject.teacher || 'Преподаватель EduAgent'}</span></div></div></div><div className="w-full rounded-2xl bg-white/80 p-4 shadow-sm sm:w-44"><div className="flex items-end justify-between"><span className="text-xs text-slate-500">Прогресс</span><strong className={`text-xl ${color.text}`}>{subject.progress || 0}%</strong></div><div className="mt-3"><ProgressBar value={subject.progress || 0} color={subject.color} /></div></div></div></div>
    <div className="mt-8 grid gap-6 xl:grid-cols-[1.55fr_.85fr]"><div><SectionTitle eyebrow="УЧЕБНЫЙ МАРШРУТ" title="Темы и материалы" /><div className="panel divide-y divide-slate-100 overflow-hidden">{topics.length ? topics.map((topic, index) => <button key={`${topic.name}-${index}`} className="flex w-full items-center gap-4 p-4 text-left transition hover:bg-slate-50 sm:p-5" onClick={() => setSelected({ ...topic, kind: 'topic' })}><div className={`grid h-11 w-11 shrink-0 place-items-center rounded-xl ${completedTopics[topicKey(subject.id, topic)] ? 'bg-emerald-50 text-emerald-600' : color.icon}`}>{completedTopics[topicKey(subject.id, topic)] ? <Check size={19} /> : <FileText size={19} />}</div><div className="min-w-0 flex-1"><div className="font-extrabold text-slate-800">{topic.name}</div><div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-slate-400"><span>{topic.type}</span></div></div><ChevronRight size={18} className="shrink-0 text-slate-400" /></button>) : <div className="p-6 text-sm text-slate-500">Тем пока нет. Преподаватель может добавить их в своём кабинете.</div>}</div>{materials.length > 0 && <div className="panel mt-5 p-5"><h3 className="mb-3 font-extrabold text-slate-900">Дополнительные материалы</h3>{materials.map(item => <button key={item.id} className="lesson-row" onClick={() => openMaterial(item)}><FileText size={18} className="text-violet-500" /><div className="min-w-0 flex-1 truncate text-left text-sm font-bold text-slate-700">{item.title}</div><ChevronRight size={16} className="text-slate-400" /></button>)}</div>}</div><div className="space-y-5"><div className="ai-card"><div className="mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-white/20"><Sparkles size={24} /></div><div className="mb-1 text-lg font-extrabold">Нужна помощь с темой?</div><p className="text-sm leading-6 text-white/80">Задай вопрос помощнику и получи подготовленное объяснение с примерами.</p><button className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-extrabold text-violet-700 transition hover:-translate-y-0.5" onClick={() => openAssistant(subject.id)}>Открыть Учебный помощника <ArrowRight size={16} /></button></div><div className="panel p-5"><div className="mb-4 flex items-center gap-2"><div className="grid h-9 w-9 place-items-center rounded-xl bg-amber-50 text-amber-600"><Lightbulb size={19} /></div><h3 className="font-extrabold text-slate-900">Практика</h3></div>{practice ? <><p className="text-sm font-bold leading-6 text-slate-700">{practice.question}</p><div className="mt-4 space-y-2">{practice.options.map((option, i) => <button key={option} className={`answer-choice text-left ${answer === i ? (i === practice.correct ? 'answer-correct' : 'answer-wrong') : ''}`} onClick={() => setAnswer(i)}><span className="answer-letter">{String.fromCharCode(65 + i)}</span><span>{option}</span></button>)}</div>{answer !== null && <div className={`mt-4 rounded-xl p-3 text-xs leading-5 ${answer === practice.correct ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-800'}`}><strong>{answer === practice.correct ? 'Верно!' : 'Попробуй ещё.'}</strong> {practice.explain}</div>}</> : <p className="text-sm leading-6 text-slate-500">Для этого предмета пока нет практического задания. Можно разобрать тему с помощником.</p>}</div></div></div>
    {selected && <div className="modal-backdrop" onMouseDown={() => setSelected(null)}><div className="modal-card" onMouseDown={e => e.stopPropagation()} role="dialog" aria-modal="true" aria-label={selected.name}><div className="flex items-start justify-between gap-4"><div className="grid h-12 w-12 place-items-center rounded-xl bg-violet-100 text-violet-600"><FileText size={23} /></div><button className="rounded-lg p-1 text-slate-400 hover:bg-slate-100" onClick={() => setSelected(null)} aria-label="Закрыть"><X size={20} /></button></div><div className="eyebrow mt-6">{selected.type || 'УЧЕБНЫЙ МАТЕРИАЛ'}</div><h2 className="mt-1 text-2xl font-extrabold text-slate-900">{selected.name}</h2><p className="mt-4 text-sm leading-7 text-slate-600">{selected.detail || 'Материал по этой теме доступен в учебном маршруте.'}</p><div className="mt-6 flex flex-wrap gap-2">{selected.kind === 'topic' && <button className="secondary-button" onClick={() => { toggleComplete(selected); setSelected(null) }}>{completedTopics[topicKey(subject.id, selected)] ? 'Отметить как не изученную' : 'Отметить изученной'}</button>}<button className="primary-button" onClick={() => { setSelected(null); openAssistant(subject.id) }}>Обсудить с помощником <ArrowRight size={16} /></button><button className="secondary-button" onClick={() => setSelected(null)}>Закрыть</button></div></div></div>}
  </div>
}
function replyFor(text, subject) {
  const t = text.toLowerCase()
  const name = subject?.name || 'математике'
  const customTopic = subject?.topics?.find(topic => topic.id && t.includes(topic.name.toLowerCase()))
  if (customTopic?.detail) return customTopic.detail
  if (/проще|простыми/.test(t)) {
    const simple = { math: 'Представь, что уравнение — это загадка: нужно найти числа, при которых левая часть превращается в ноль. Для x² − 5x + 6 это 2 и 3.', english: 'Present Perfect говорит о том, что что-то уже произошло и результат важен сейчас: I have finished — «я уже закончил».', physics: 'Сила заставляет тело менять скорость. Чем больше сила — тем больше ускорение; чем тяжелее тело — тем меньше ускорение.', chemistry: 'В реакции окисления один участник отдаёт электроны, а другой их принимает. Они как будто обмениваются «зарядом».', history: 'Казахское ханство возникло, когда Керей и Жанибек объединили людей и создали самостоятельное государство.' }
    return simple[subject?.id] || 'Разберём по шагам: сначала выдели известные данные, затем найди правило и проверь ответ на простом примере.'
  }
  if (/пример/.test(t)) {
    const examples = { math: 'Пример: x² − 7x + 12 = 0. Найди два числа, сумма которых 7, а произведение 12. Это 3 и 4. Значит, корни: x = 3 и x = 4.', english: 'Пример: She has already eaten breakfast. — Она уже позавтракала. Результат важен сейчас: она не голодна.', physics: 'Пример: если на тележку массой 2 кг действует сила 10 Н, то ускорение a = F/m = 10/2 = 5 м/с².', chemistry: 'Пример: Zn + 2HCl → ZnCl₂ + H₂. Цинк отдаёт электроны, ионы водорода их принимают.', history: 'Пример: в XV веке Керей и Жанибек переселились в Могулистан. Это стало важным шагом к образованию Казахского ханства.' }
    return examples[subject?.id] || 'Давай возьмём знакомую задачу, выделим данные и применим правило по шагам.'
  }
  if (/задан|упражнен|проверь/.test(t)) {
    const tasks = { math: 'Попробуй сам: реши x² − 8x + 15 = 0. Подсказка: нужны два числа с суммой 8 и произведением 15. Ответ для проверки: x = 3 и x = 5.', english: 'Задание: переведи «Я уже прочитал эту книгу» с помощью Present Perfect. Ответ для проверки: I have already read this book.', physics: 'Задание: тело массой 4 кг движется с ускорением 2 м/с². Найди силу. Ответ для проверки: F = ma = 8 Н.', chemistry: 'Задание: определи, какой газ выделится в реакции Mg + 2HCl → MgCl₂ + ?. Ответ для проверки: H₂.', history: 'Задание: назови двух основателей Казахского ханства. Ответ для проверки: Керей и Жанибек.' }
    return tasks[subject?.id] || 'Задание: сформулируй главное правило темы своими словами и придумай один пример его применения.'
  }
  if (/дискриминант|квадратн|парабол/.test(t)) return 'Чтобы решить квадратное уравнение ax² + bx + c = 0, вычисли дискриминант D = b² − 4ac. Если D > 0, корней два; если D = 0 — один; если D < 0 — действительных корней нет. Затем используй формулу x = (−b ± √D) / 2a.'
  if (/линейн.*уравнен/.test(t)) return 'В линейном уравнении перенеси числа в одну сторону, неизвестное — в другую. Например, 3x − 7 = 11: 3x = 18, значит x = 6.'
  if (/present perfect|англ.*времен/.test(t)) return 'Present Perfect строится так: have/has + третья форма глагола. Оно помогает сказать о действии, которое произошло раньше, но связано с настоящим. Например: I have lost my key — ключ потерян, поэтому сейчас его нет.'
  if (/ньютон|ускорен|закон.*сил/.test(t)) return 'Второй закон Ньютона связывает силу, массу и ускорение: F = ma. Если сила растёт, ускорение тоже растёт. Если масса больше, той же силе сложнее разогнать тело.'
  if (/реакц|окисл|электрон/.test(t)) return 'В окислительно-восстановительной реакции электроны переходят от одного участника к другому. Окисление — отдача электронов, восстановление — принятие. Степень окисления помогает увидеть этот обмен.'
  if (/ханств|керей|жанибек/.test(t)) return 'Казахское ханство сформировалось в XV веке. Его основателями считают Керея и Жанибека. Для понимания темы полезно запомнить причины переселения, объединение племён и значение самостоятельной власти.'
  return `Для вопроса по предмету «${name}» у меня пока нет подготовленного ответа. Открой нужную тему в предмете или выбери «Объясни проще», «Приведи пример» либо «Дай задание».` 
}
function AssistantPage({ allSubjects, activeSubject, setActiveSubject, storageKey }) {
  const [messages, setMessages] = useStoredState(storageKey, [{ id: 1, from: 'bot', text: 'Привет! Я учебный помощник EduAgent. Выбери предмет и спроси о теме — я покажу подготовленное объяснение, пример или задание.' }])
  const [draft, setDraft] = useState('')
  const [typing, setTyping] = useState(false)
  const endRef = useRef(null)
  const timerRef = useRef(null)
  const subject = allSubjects.find(x => x.id === activeSubject) || allSubjects[0]
  const visibleMessages = messages.filter(message => !message.subjectId || message.subjectId === activeSubject)
  useEffect(() => { endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) }, [messages, typing, activeSubject])
  useEffect(() => () => clearTimeout(timerRef.current), [])
  const send = (value) => {
    const text = value.trim(); if (!text || typing) return
    setMessages(prev => [...prev, { id: crypto.randomUUID(), subjectId: activeSubject, from: 'user', text }]); setDraft(''); setTyping(true)
    timerRef.current = setTimeout(() => { setMessages(prev => [...prev, { id: crypto.randomUUID(), subjectId: activeSubject, from: 'bot', text: replyFor(text, subject) }]); setTyping(false) }, 900)
  }
  return <div className="page-enter"><div className="mb-7"><div className="eyebrow mb-1">ПОДДЕРЖКА В УЧЁБЕ</div><h1 className="page-title">Учебный помощник <span className="align-middle rounded-full bg-violet-100 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-violet-700">Офлайн</span></h1><p className="page-subtitle">Задавай вопросы и изучай темы в удобном темпе.</p></div><div className="grid gap-6 xl:grid-cols-[1fr_260px]"><div className="chat-shell"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4 sm:p-5"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-gradient-to-br from-violet-500 to-blue-600 text-white"><Sparkles size={21} /></div><div><div className="font-extrabold text-slate-900">Помощник EduAgent</div><div className="mt-0.5 flex items-center gap-1.5 text-xs text-emerald-600"><span className="h-1.5 w-1.5 rounded-full bg-emerald-500" /> Готов помочь</div></div></div><select className="select-field !w-auto !py-2 text-xs" value={activeSubject} onChange={e => setActiveSubject(e.target.value)} aria-label="Предмет чата">{allSubjects.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select><button className="icon-action" title="Очистить переписку по предмету" aria-label="Очистить переписку по предмету" onClick={() => setMessages(previous => previous.filter(message => message.subjectId !== activeSubject))}><Trash2 size={17} /></button></div><div className="border-b border-violet-100 bg-violet-50 px-5 py-2.5 text-xs leading-5 text-violet-700"><strong>Офлайн-режим.</strong> Ответы заранее подготовлены для типовых вопросов. Помощник не использует нейросеть и может не знать ответ на произвольный вопрос.</div><div className="chat-messages" aria-live="polite">{visibleMessages.map(message => <div key={message.id} className={`chat-line ${message.from === 'user' ? 'justify-end' : ''}`}>{message.from === 'bot' && <div className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-violet-100 text-violet-600"><Sparkles size={15} /></div>}<div className={`chat-bubble ${message.from === 'user' ? 'chat-bubble-user' : 'chat-bubble-bot'}`}>{message.text}</div></div>)}{typing && <div className="chat-line"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-violet-100 text-violet-600"><Sparkles size={15} /></div><div className="chat-bubble chat-bubble-bot flex items-center gap-1.5" aria-label="Помощник печатает"><span className="typing-dot" /><span className="typing-dot" /><span className="typing-dot" /></div></div>}<div ref={endRef} /></div><div className="border-t border-slate-100 p-4"><div className="mb-3 flex flex-wrap gap-2">{[['Объясни проще', Lightbulb], ['Приведи пример', BookOpen], ['Дай задание', Target]].map(([label, Icon]) => <button key={label} className="quick-action" onClick={() => send(label)} disabled={typing}><Icon size={14} /> {label}</button>)}</div><form className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 p-2 focus-within:border-violet-300 focus-within:bg-white" onSubmit={e => { e.preventDefault(); send(draft) }}><input className="min-w-0 flex-1 bg-transparent px-2 text-sm outline-none placeholder:text-slate-400" value={draft} onChange={e => setDraft(e.target.value)} placeholder="Напиши вопрос по теме..." maxLength={500} aria-label="Вопрос помощнику" /><button type="submit" className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-violet-600 text-white transition hover:bg-violet-700 disabled:opacity-50" disabled={!draft.trim() || typing} aria-label="Отправить сообщение"><Send size={18} /></button></form></div></div><div className="space-y-5"><div className="panel p-5"><div className="mb-2 flex items-center gap-2 text-sm font-extrabold text-slate-900"><Lightbulb size={18} className="text-amber-500" /> С чего начать?</div><p className="mb-4 text-xs leading-5 text-slate-500">Нажми на пример вопроса — ответ появится в чате.</p><div className="space-y-2">{[`Объясни тему «${subject.current || subject.name}»`, 'Приведи пример', 'Дай задание'].map(q => <button key={q} className="w-full rounded-xl border border-slate-100 p-3 text-left text-xs font-semibold leading-5 text-slate-600 transition hover:border-violet-200 hover:bg-violet-50 hover:text-violet-700" onClick={() => send(q)} disabled={typing}>{q}</button>)}</div></div><div className="rounded-2xl bg-gradient-to-br from-blue-50 to-violet-50 p-5"><div className="mb-2 text-sm font-extrabold text-slate-900">Учись в своём темпе</div><p className="text-xs leading-5 text-slate-500">Переключай предмет и уточняй вопросы. Для реального обучения проверяй ответы по учебнику и с преподавателем.</p></div></div></div></div>
}
function ExamPage({ results, setResults, go, storageKey }) {
  const [examSession, setExamSession] = useStoredState(storageKey, { mode: 'intro', index: 0, answers: Array(examQuestions.length).fill(null), currentResult: null })
  const { mode, index, answers, currentResult } = examSession
  const setMode = value => setExamSession(previous => ({ ...previous, mode: value }))
  const setIndex = value => setExamSession(previous => ({ ...previous, index: value }))
  const setAnswers = value => setExamSession(previous => ({ ...previous, answers: typeof value === 'function' ? value(previous.answers) : value }))
  const setCurrentResult = value => setExamSession(previous => ({ ...previous, currentResult: value }))
  const answered = answers.filter(x => x !== null).length
  const start = () => { setAnswers(Array(examQuestions.length).fill(null)); setIndex(0); setCurrentResult(null); setMode('active') }
  const finish = () => {
    const score = examQuestions.reduce((n, q, i) => n + (answers[i] === q.correct ? 1 : 0), 0)
    const result = { id: Date.now(), date: new Date().toISOString(), score, total: examQuestions.length, answers, subject: 'Математика' }
    setResults(prev => [result, ...prev]); setCurrentResult(result); setMode('result'); window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  if (mode === 'intro') return <div className="page-enter"><div className="eyebrow mb-1">ПРОВЕРКА ЗНАНИЙ</div><h1 className="page-title">Пробный экзамен</h1><p className="page-subtitle">Проверь, насколько уверенно ты владеешь темами математики за 9 класс.</p><div className="mx-auto mt-10 max-w-3xl overflow-hidden rounded-[28px] border border-slate-100 bg-white shadow-soft"><div className="relative overflow-hidden bg-gradient-to-br from-violet-600 via-indigo-600 to-blue-600 p-8 text-white sm:p-10"><div className="relative z-10"><div className="mb-5 grid h-14 w-14 place-items-center rounded-2xl bg-white/20"><ClipboardCheck size={27} /></div><div className="text-2xl font-extrabold tracking-tight sm:text-3xl">Математика · 9 класс</div><p className="mt-2 max-w-md text-sm leading-6 text-white/75">Задания по алгебре, геометрии, вероятности и функциям. Результат с разбором будет доступен сразу.</p></div><div className="absolute -right-10 -top-16 h-64 w-64 rounded-full border-[35px] border-white/10" /></div><div className="grid gap-4 p-7 sm:grid-cols-3 sm:p-8"><div className="exam-info"><CircleHelp size={20} className="text-violet-600" /><strong>15 вопросов</strong><span>По основным темам</span></div><div className="exam-info"><Clock3 size={20} className="text-blue-600" /><strong>≈ 20 минут</strong><span>Без ограничения времени</span></div><div className="exam-info"><BarChart3 size={20} className="text-emerald-600" /><strong>Мгновенный итог</strong><span>Сохранится в прогрессе</span></div></div><div className="flex flex-wrap items-center justify-between gap-4 border-t border-slate-100 px-8 py-6"><p className="max-w-sm text-xs leading-5 text-slate-500">Можно переходить между вопросами. Неотвеченные задания засчитываются как неверные.</p><button className="primary-button" onClick={start}>Начать экзамен <ArrowRight size={17} /></button></div></div></div>
  if (mode === 'result' && currentResult) return <div className="page-enter"><div className="eyebrow mb-1">ЭКЗАМЕН ЗАВЕРШЁН</div><h1 className="page-title">Твой результат</h1><p className="page-subtitle">Разберём, что получилось хорошо и на какие темы обратить внимание.</p><div className="mt-8 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><div className="panel p-7 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-violet-100 text-violet-600"><Target size={30} /></div><div className="mt-5 text-5xl font-extrabold tracking-tight text-slate-900">{pct(currentResult.score, currentResult.total)}<span className="text-2xl text-violet-600">%</span></div><div className="mt-1 text-sm text-slate-500">{currentResult.score} правильных из {currentResult.total}</div><div className="mx-auto mt-6 max-w-xs"><ProgressBar value={pct(currentResult.score, currentResult.total)} /></div><p className="mt-6 text-sm leading-6 text-slate-500">{currentResult.score >= 12 ? 'Отличный результат! Продолжай в том же духе.' : currentResult.score >= 8 ? 'Хорошая база. Разбор ошибок поможет стать увереннее.' : 'Есть над чем поработать. Начни с тем, где возникли ошибки.'}</p><div className="mt-7 flex flex-col gap-2"><button className="primary-button justify-center" onClick={() => go('progress')}>Посмотреть прогресс <ArrowRight size={16} /></button><button className="secondary-button justify-center" onClick={start}>Пройти ещё раз</button></div></div><div className="panel p-6"><h2 className="text-lg font-extrabold text-slate-900">Разбор заданий</h2><p className="mt-1 text-xs text-slate-500">Нажми на вопрос и проверь объяснение.</p><div className="mt-5 max-h-[620px] space-y-2 overflow-y-auto pr-1">{examQuestions.map((q, i) => { const correct = currentResult.answers[i] === q.correct; return <details key={i} className="group rounded-xl border border-slate-100 bg-white p-4 open:border-violet-200 open:bg-violet-50/40"><summary className="flex cursor-pointer list-none items-center gap-3"><div className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg text-xs font-extrabold ${correct ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{correct ? <Check size={17} /> : i + 1}</div><span className="min-w-0 flex-1 truncate text-sm font-bold text-slate-700">{q.q}</span><ChevronDown size={16} className="text-slate-400 transition group-open:rotate-180" /></summary><div className="ml-11 mt-3 text-xs leading-5 text-slate-600"><div>Твой ответ: <strong>{currentResult.answers[i] === null ? 'нет ответа' : q.options[currentResult.answers[i]]}</strong></div><div>Правильный ответ: <strong className="text-emerald-700">{q.options[q.correct]}</strong></div><p className="mt-2">{q.explanation}</p></div></details> })}</div></div></div></div>
  const q = examQuestions[index]
  return <div className="page-enter"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow mb-1">ПРОБНЫЙ ЭКЗАМЕН · МАТЕМАТИКА</div><h1 className="page-title">Вопрос {index + 1} <span className="text-slate-400">/ {examQuestions.length}</span></h1></div><div className="date-pill"><CheckCircle2 size={16} /> {answered} из {examQuestions.length} отвечено</div></div><div className="mb-7"><ProgressBar value={pct(answered, examQuestions.length)} height="h-2.5" /></div><div className="grid gap-6 lg:grid-cols-[1fr_250px]"><div className="panel overflow-hidden"><div className="border-b border-slate-100 px-6 py-5 sm:px-8"><span className="rounded-full bg-violet-50 px-3 py-1.5 text-xs font-bold text-violet-700">{q.topic}</span><h2 className="mt-5 text-xl font-extrabold leading-8 tracking-tight text-slate-900 sm:text-2xl">{q.q}</h2><p className="mt-2 text-sm text-slate-400">Выбери один правильный ответ</p></div><div className="space-y-3 p-6 sm:p-8">{q.options.map((option, i) => <button key={i} className={`exam-choice ${answers[index] === i ? 'exam-choice-selected' : ''}`} onClick={() => setAnswers(prev => prev.map((a, n) => n === index ? i : a))}><span className="exam-letter">{String.fromCharCode(65 + i)}</span><span className="flex-1 text-left">{option}</span>{answers[index] === i && <CheckCircle2 size={19} className="text-violet-600" />}</button>)}</div><div className="flex flex-wrap justify-between gap-3 border-t border-slate-100 px-6 py-5 sm:px-8"><button className="secondary-button" onClick={() => setIndex(Math.max(0, index - 1))} disabled={index === 0}><ChevronLeft size={17} /> Назад</button>{index === examQuestions.length - 1 ? <button className="primary-button" onClick={finish}>Завершить тест <Check size={17} /></button> : <button className="primary-button" onClick={() => setIndex(index + 1)}>Следующий вопрос <ChevronRight size={17} /></button>}</div></div><div className="space-y-5"><div className="panel p-5"><h3 className="font-extrabold text-slate-900">Навигация по заданиям</h3><p className="mt-1 text-xs text-slate-400">Выбери номер, чтобы перейти к вопросу.</p><div className="mt-5 grid grid-cols-5 gap-2">{examQuestions.map((_, i) => <button key={i} className={`question-dot ${i === index ? 'question-dot-current' : answers[i] !== null ? 'question-dot-answered' : ''}`} onClick={() => setIndex(i)} aria-label={`Вопрос ${i + 1}`}>{i + 1}</button>)}</div><div className="mt-5 flex flex-wrap gap-4 text-[11px] text-slate-500"><span className="flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded bg-violet-600" /> Текущий</span><span className="flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded bg-violet-100" /> Отвечен</span></div></div><div className="rounded-2xl bg-blue-50 p-5 text-xs leading-5 text-blue-800"><strong>Совет:</strong> если вопрос кажется сложным, перейди к следующему и вернись позже.</div></div></div></div>
}
function ProgressPage({ results, allSubjects, go }) {
  const history = results.slice().reverse().map(r => ({ date: fmtDate(r.date), score: r.score, total: r.total }))
  const latest = results[0]
  const average = results.length ? Math.round(results.reduce((sum, r) => sum + pct(r.score, r.total), 0) / results.length) : 0
  const topicStats = latest ? Object.entries(examQuestions.reduce((acc, q, i) => { const item = acc[q.topic] || { right: 0, total: 0 }; item.total += 1; item.right += latest.answers[i] === q.correct ? 1 : 0; acc[q.topic] = item; return acc }, {})).map(([topic, x]) => ({ topic, value: pct(x.right, x.total) })).sort((a, b) => b.value - a.value) : []
  const strong = topicStats.filter(x => x.value >= 70).slice(0, 3)
  const weak = topicStats.filter(x => x.value < 70).sort((a, b) => a.value - b.value).slice(0, 3)
  return <div className="page-enter"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow mb-1">АНАЛИТИКА ОБУЧЕНИЯ</div><h1 className="page-title">Мой прогресс</h1><p className="page-subtitle">Следи за результатами и находи темы, которым стоит уделить внимание.</p></div><button className="primary-button" onClick={() => go('exam')}>Пройти тест <ArrowRight size={16} /></button></div><div className="grid gap-4 sm:grid-cols-3"><div className="stat-card"><div className="stat-icon bg-violet-50 text-violet-600"><Target size={21} /></div><div><div className="stat-number">{results.length ? `${average}%` : '—'}</div><div className="stat-label">Средний результат</div></div></div><div className="stat-card"><div className="stat-icon bg-blue-50 text-blue-600"><ClipboardCheck size={21} /></div><div><div className="stat-number">{results.length}</div><div className="stat-label">Моих тестов</div></div></div><div className="stat-card"><div className="stat-icon bg-emerald-50 text-emerald-600"><TrendingUp size={21} /></div><div><div className="stat-number">{latest ? `${latest.score}/${latest.total}` : '—'}</div><div className="stat-label">Последний тест</div></div></div></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.85fr]"><div className="panel p-6"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><div className="eyebrow mb-1">ДИНАМИКА</div><h2 className="text-lg font-extrabold text-slate-900">Результаты по математике</h2></div><div className="rounded-full bg-violet-50 px-3 py-1.5 text-[11px] font-bold text-violet-700">Из 15 заданий</div></div>{!history.length && <p className="mb-3 rounded-xl bg-slate-50 p-3 text-xs text-slate-500">Пройди пробный экзамен, чтобы увидеть динамику результатов.</p>}<div className="h-[260px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={history} margin={{ top: 10, right: 10, left: -25, bottom: 0 }}><defs><linearGradient id="progressFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7357ec" stopOpacity={0.28} /><stop offset="100%" stopColor="#7357ec" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid stroke="#edf0f7" strokeDasharray="4 4" vertical={false} /><XAxis dataKey="date" tickLine={false} axisLine={false} tick={{ fill: '#9aa5b8', fontSize: 11 }} /><YAxis domain={[0, 15]} ticks={[0, 5, 10, 15]} tickLine={false} axisLine={false} tick={{ fill: '#9aa5b8', fontSize: 11 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #eef0f7', boxShadow: '0 12px 30px rgba(20,30,80,.08)' }} formatter={value => [`${value} из 15`, 'Верно']} /><Area type="monotone" dataKey="score" stroke="#7357ec" strokeWidth={3} fill="url(#progressFill)" dot={{ r: 4, fill: '#fff', stroke: '#7357ec', strokeWidth: 2 }} activeDot={{ r: 6 }} /></AreaChart></ResponsiveContainer></div><p className="mt-2 text-[11px] text-slate-400">Результаты сохраняются только в этом браузере.</p></div><div className="panel p-6"><div className="eyebrow mb-1">ПО ПРЕДМЕТАМ</div><h2 className="text-lg font-extrabold text-slate-900">Успеваемость</h2><div className="mt-5 h-[258px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={allSubjects.slice(0, 5).map(s => ({ name: s.short.length > 12 ? s.short.slice(0, 10) + '…' : s.short, progress: s.progress || 0 }))} layout="vertical" margin={{ top: 0, right: 15, left: 2, bottom: 0 }}><CartesianGrid stroke="#edf0f7" strokeDasharray="4 4" horizontal={false} /><XAxis type="number" domain={[0, 100]} hide /><YAxis type="category" dataKey="name" width={100} axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 11 }} /><Tooltip cursor={{ fill: '#f8f7ff' }} formatter={value => [`${value}%`, 'Прогресс']} /><Bar dataKey="progress" fill="#7460ea" radius={[0, 7, 7, 0]} barSize={13} /></BarChart></ResponsiveContainer></div><p className="mt-2 text-[11px] text-slate-400">Прогресс считается по темам, которые ты отметил изученными.</p></div></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><div className="panel p-6"><div className="mb-5 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><TrendingUp size={19} /></div><div><div className="font-extrabold text-slate-900">Сильные темы</div><div className="text-xs text-slate-400">Уже хорошо получается</div></div></div>{strong.length ? strong.map(item => <div key={item.topic} className="topic-meter"><div className="mb-2 flex justify-between gap-3 text-xs"><span className="font-bold text-slate-700">{item.topic}</span><strong className="text-emerald-600">{item.value}%</strong></div><div className="h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${item.value}%` }} /></div></div>) : <p className="text-sm text-slate-500">После следующего теста здесь появятся темы с сильными результатами.</p>}</div><div className="panel p-6"><div className="mb-5 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-amber-50 text-amber-600"><Target size={19} /></div><div><div className="font-extrabold text-slate-900">Требуют внимания</div><div className="text-xs text-slate-400">Хороший повод повторить</div></div></div>{weak.length ? weak.map(item => <div key={item.topic} className="topic-meter"><div className="mb-2 flex justify-between gap-3 text-xs"><span className="font-bold text-slate-700">{item.topic}</span><strong className="text-amber-600">{item.value}%</strong></div><div className="h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-amber-500" style={{ width: `${item.value}%` }} /></div></div>) : <p className="text-sm text-slate-500">Отлично! В последнем тесте нет тем с результатом ниже 70%.</p>}</div></div><div className="mt-6 panel p-6"><SectionTitle eyebrow="ИСТОРИЯ" title="Последние тесты" /><div className="space-y-2">{results.length ? results.slice(0, 5).map(result => <div key={result.id} className="flex items-center gap-4 rounded-xl border border-slate-100 p-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-50 text-violet-600"><ClipboardCheck size={18} /></div><div className="flex-1"><div className="text-sm font-bold text-slate-800">Математика · пробный экзамен</div><div className="text-xs text-slate-400">{new Date(result.date).toLocaleString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</div></div><strong className="text-sm text-violet-700">{result.score}/{result.total}</strong></div>) : <div className="rounded-xl bg-slate-50 p-5 text-sm leading-6 text-slate-500">Пока нет результатов. Пройдите пробный экзамен, чтобы увидеть их здесь.</div>}</div></div></div>
}
function Workspace({ account, accounts, setAccounts, logout }) {
  const profile = `eduagent-user-${account.id}-`
  const [results, setResults] = useStoredState(`${profile}results`, [])
  const [completedTopics, setCompletedTopics] = useStoredState(`${profile}completed-topics`, {})
  const [activeSubject, setActiveSubject] = useStoredState(`${profile}chat-subject`, 'math')
  const [customSubjects, setCustomSubjects] = useStoredState('eduagent-subjects', [])
  const [customTopics, setCustomTopics] = useStoredState('eduagent-topics', [])
  const [customMaterials, setCustomMaterials] = useStoredState('eduagent-materials', [])
  const [sessions, setSessions] = useStoredState('eduagent-sessions', [])
  const [storageError, setStorageError] = useState(false)
  const [route, go] = useRoute()
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const onError = () => setStorageError(true)
    window.addEventListener('eduagent-storage-error', onError)
    return () => window.removeEventListener('eduagent-storage-error', onError)
  }, [])
  useEffect(() => {
    if (account.role === 'teacher' && route !== 'teacher') go('teacher')
    if (account.role === 'student' && (route === 'teacher' || route === 'login')) go('home')
  }, [account.role, route])

  const allSubjects = useMemo(() => [...subjects, ...customSubjects].map(subject => {
    const extra = customTopics.filter(topic => topic.subjectId === subject.id).map(topic => ({ id: topic.id, name: topic.title, type: 'Тема преподавателя', detail: topic.description }))
    const topics = [...(subject.topics || []), ...extra]
    const lessons = topics.filter(topic => completedTopics[topicKey(subject.id, topic)]).length
    return { ...subject, topics, lessons, total: topics.length, progress: topics.length ? pct(lessons, topics.length) : 0, current: topics.find(topic => !completedTopics[topicKey(subject.id, topic)])?.name || (topics.length ? 'Все темы изучены' : 'Темы пока не добавлены') }
  }), [customSubjects, customTopics, completedTopics])

  const openAssistant = id => { setActiveSubject(id); go('assistant') }
  const subject = route.startsWith('subject/') ? allSubjects.find(item => item.id === route.split('/')[1]) : null
  let page
  if (account.role === 'teacher') {
    page = <TeacherPage allSubjects={allSubjects} customSubjects={customSubjects} setCustomSubjects={setCustomSubjects} customTopics={customTopics} setCustomTopics={setCustomTopics} customMaterials={customMaterials} setCustomMaterials={setCustomMaterials} sessions={sessions} setSessions={setSessions} accounts={accounts} setAccounts={setAccounts} />
  } else if (subject) page = <SubjectPage key={subject.id} subject={subject} customMaterials={customMaterials} completedTopics={completedTopics} setCompletedTopics={setCompletedTopics} go={go} openAssistant={openAssistant} />
  else if (route === 'subjects') page = <SubjectsPage allSubjects={allSubjects} go={go} />
  else if (route === 'assistant') page = <AssistantPage allSubjects={allSubjects} activeSubject={activeSubject} setActiveSubject={setActiveSubject} storageKey={`${profile}chat-history`} />
  else if (route === 'exam') page = <ExamPage results={results} setResults={setResults} go={go} storageKey={`${profile}exam-session`} />
  else if (route === 'progress') page = <ProgressPage results={results} allSubjects={allSubjects} go={go} />
  else page = <HomePage allSubjects={allSubjects} results={results} sessions={sessions} go={go} studentName={account.name} />

  return <div className="app-shell"><Sidebar route={route} go={go} account={account} logout={logout} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} /><div className="main-column"><Header route={route} account={account} go={go} logout={logout} setMobileOpen={setMobileOpen} /><main className="mx-auto w-full max-w-[1420px] p-5 pb-14 sm:p-8 lg:p-9">{storageError && <div role="alert" className="mb-5 rounded-xl bg-rose-50 p-4 text-sm font-bold text-rose-800">Память браузера заполнена или недоступна. Освободите место и сохраните резервную копию данных.</div>}{page}</main></div></div>
}

export default function App() {
  const [accounts, setAccounts] = useStoredState('eduagent-accounts', [])
  const [sessionId, setSessionId] = useState(() => sessionStorage.getItem('eduagent-current-user'))
  const account = accounts.find(item => item.id === sessionId)
  const signIn = selected => {
    sessionStorage.setItem('eduagent-current-user', selected.id)
    setSessionId(selected.id)
    window.location.hash = selected.role === 'teacher' ? '/teacher' : '/home'
  }
  const setup = selected => { setAccounts([selected]); signIn(selected) }
  const logout = () => {
    sessionStorage.removeItem('eduagent-current-user')
    setSessionId(null)
    window.location.hash = '/login'
  }
  if (!account) return <AuthPage accounts={accounts} onSetup={setup} onLogin={signIn} />
  return <Workspace key={account.id} account={account} accounts={accounts} setAccounts={setAccounts} logout={logout} />
}
